import json
try:
    from urlparse import urljoin
except ImportError:
    from urllib.parse import urljoin

from .session import Session
from .exceptions import OperationNotPermittedError


DEFAULT_USER = 'Nemuadmin'
DEFAULT_PASSWORD = 'nemuuser'
DEFAULT_PORT = 8666


def create_api_client(base_url,
                      username=DEFAULT_USER,
                      password=DEFAULT_PASSWORD,
                      port=DEFAULT_PORT,
                      timeout=None):
    """Setup and return a new API object.

    :param str base_url: host to connect to. If no schema is supplied,
        `https://` is used by default. It should not contain port designator -
        port is specified via `port` parameter.
    :param str username: (Optional) Username to use for authentication -
        `"Nemuadmin"` by default.
    :param str password:  (Optional) Password to use for authentication -
        `"nemuuser"` by default.
    :param int port: Port of the target API server - 8666 by default
    :param int timeout: (Optional) timeout for the authentication process
        (in seconds) - None (wait indefinitely) by default.
    :raises ConnectionError: if server responds with anything other than
        HTTP 200 during authentication.
    :raises requests.Timeout: If timeout occured.
    :return: Initialized API object.
    :rtype: RapManagerApi
    """
    session = Session(base_url=base_url, port=port,
                      username=username, password=password, timeout=timeout)
    return RapManagerApi(session)


class RapManagerApi(object):
    """API Client for RAP Manager."""

    def __init__(self, session):
        self._eps_endpoint = ApiEndpoint(session,
                                         'ethernetPortSecurity')
        self._sea_endpoint = ApiEndpoint(session,
                                         'serviceAccess')
        self._rra_endpoint = ApiEndpoint(session,
                                         'restrictedAccess')

    def enable_ethernet_port_security(self):
        self._eps_endpoint.post({'ethernetPortSecurityEnabled': True})

    def disable_ethernet_port_security(self):
        self._eps_endpoint.post({'ethernetPortSecurityEnabled': False})

    @property
    def ethernet_port_security_enabled(self):
        data = self._eps_endpoint.get()
        return data['ethernetPortSecurityEnabled'] == 'true'

    def enable_service_account_ssh(self):
        self._sea_endpoint.post({'sshAccess': 'enabled'})

    def disable_service_account_ssh(self):
        self._sea_endpoint.post({'sshAccess': 'disabled'})

    @property
    def service_account_ssh_enabled(self):
        data = self._sea_endpoint.get()
        return data['sshAccess'] == 'enabled'

    def enable_service_port(self):
        self._sea_endpoint.post({'rndPortAccess': 'enabled'})

    def disable_service_port(self):
        self._sea_endpoint.post({'rndPortAccess': 'disabled'})

    @property
    def service_port_enabled(self):
        data = self._sea_endpoint.get()
        return data['rndPortAccess'] == 'enabled'

    def enable_restricted_root_access(self):
        if self.connected_to_vnf:
            exc_msg = "Changing access not possible: connected to VNF."
            raise OperationNotPermittedError(exc_msg)

        self._rra_endpoint.post({'restrictedAccessEnabled': True})

    def disable_restricted_root_access(self):
        if self.connected_to_vnf:
            exc_msg = "Changing access not possible: connected to VNF."
            raise OperationNotPermittedError(exc_msg)

        self._rra_endpoint.post({'restrictedAccessEnabled': False})

    @property
    def connected_to_vnf(self):
        data = self._rra_endpoint.get()
        return data['status']['vnfConnectionStatus'] == 'connected'

    @property
    def restricted_root_access_enabled(self):
        data = self._rra_endpoint.get()
        return data['status']['restrictedAccessEnabled'] == 'true'


class ApiEndpoint(object):
    """Helper class that simplifies sending requests to a given endpoint

    Class fields:
        URL_BASE - url prefix that will be added to each requests target url
        VERIFY_TLS - if True, `verify=True` will be given to
            Session.send_request.
    """
    URL_BASE = 'api/v1/'
    VERIFY_TLS = False

    def __init__(self, session, endpoint_url):
        self._endpoint_url = urljoin(self.URL_BASE, endpoint_url)
        self._session = session

    def get(self):
        return self.send_request().json()

    def post(self, data):
        return self.send_request(method='POST', data=data).json()

    def send_request(self, method='GET', data=None, **kwargs):
        data = json.dumps(data)
        return self._session.send_request(self._endpoint_url, method=method,
                                          verify=self.VERIFY_TLS, data=data,
                                          **kwargs)
